/*
 * Sharing is what puts a step in front of the learner (SCOPE: learners never see a step
 * that is not shared), so a step is only shared when it can stand on its own:
 *  - every step needs a title;
 *  - homework needs a brief and a due date;
 *  - a check-in needs a send date, or "N days after" a step (DBU-10: that step may not have
 *    its date yet; the check-in goes once it has one).
 * A live session is ready as it is: "to book" is a state the learner can act on.
 * Named steps that are not ready are refused in a sentence; `allReady` shares every
 * ready draft and says how many it left. Unsharing is always allowed.
 * One doorbell for the learner, so their page re-reads once.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const planId = String(Inputs.planId || '');
    const plans = planId ? await R.query('Plan', { objectId: { equalTo: planId } }, { limit: 2, plain: true }) : [];
    if (plans.length !== 1) return refuse('That plan is no longer there. Reload the page.');
    const learner = plans[0].learner;
    const steps = await R.query('Step', { plan: { equalTo: planId } }, { limit: 1000, plain: true });
    const share = Inputs.shared === true;
    const missing = (s) => {
      if (!String(s.title || '').trim()) return 'a title';
      if (s.kind === 'homework' && !String(s.brief || '').trim() && !s.dueAt) return 'a brief and a due date';
      if (s.kind === 'homework' && !String(s.brief || '').trim()) return 'a brief';
      if (s.kind === 'homework' && !s.dueAt) return 'a due date';
      if (s.kind === 'checkin' && !s.sendsAt && !(s.sendAfter && s.sendAfter.step)) return 'a send date';
      return '';
    };

    let chosen;
    let left = 0;
    if (Inputs.allReady === true && share) {
      const drafts = steps.filter((s) => s.shared !== true);
      chosen = drafts.filter((s) => !missing(s));
      left = drafts.length - chosen.length;
    } else {
      const ids = Array.isArray(Inputs.stepIds) ? Inputs.stepIds.map(String) : [];
      chosen = steps.filter((s) => ids.includes(s.objectId));
      if (!ids.length || chosen.length !== ids.length) return refuse('That step is no longer in the plan. Reload the page.');
      if (share) {
        const notReady = chosen.find((s) => missing(s));
        if (notReady) return refuse('Give “' + (notReady.title || 'this step') + '” ' + missing(notReady) + ' before you share it.');
      }
    }

    let changed = 0;
    for (const s of chosen) {
      if ((s.shared === true) !== share) {
        await R.save(s.objectId, { shared: share }, { className: 'Step' });
        changed++;
      }
    }
    if (changed) {
      await R.create('Doorbell', { learner, topic: 'plan' }, { acl: { [learner]: { read: true }, 'role:staff': { read: true } } });
    }
    Outputs.changed = changed;
    Outputs.left = left;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:shareSteps]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
